Integer seen = 0;
Integer afterSwitch = 0;
for (Integer i = 0; i < 3; i++) {
  switch on i {
    when 0 {
      seen++;
      break;
    }
    when 1 {
      continue;
    }
    when else {
      seen = seen + 10;
    }
  }
  afterSwitch++;
}
System.assertEquals(11, seen);
System.assertEquals(2, afterSwitch);
Integer cleaned = 0;
Integer loopSeen = 0;
for (Integer i = 0; i < 4; i++) {
  try {
    if (i == 1) {
      continue;
    }
    if (i == 2) {
      break;
    }
    loopSeen++;
  } finally {
    cleaned++;
  }
}
System.assertEquals(1, loopSeen);
System.assertEquals(3, cleaned);
Integer overridden = 0;
while (overridden < 1) {
  try {
    break;
  } finally {
    overridden++;
    continue;
  }
}
System.assertEquals(1, overridden);
String caught = '';
try {
  try {
    throw new QueryException('bad query');
  } catch (Exception e) {
    throw;
  }
} catch (DmlException | QueryException e) {
  caught = e.getTypeName() + ':' + e.getMessage();
  System.assert(e.getLineNumber() > 0);
  System.assert(e.getStackTraceString() != '');
}
System.assertEquals('System.QueryException:bad query', caught);

